prompt --application/shared_components/user_interface/templates/region/terminal_window
begin
wwv_flow_imp_shared.create_plug_template(
 p_id=>wwv_flow_imp.id(192326357393333830)
,p_layout=>'TABLE'
,p_template=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<section class="amc-TTerminalWindow #REGION_CSS_CLASSES#" id="#REGION_STATIC_ID#" #REGION_ATTRIBUTES# aria-labelledby="#REGION_STATIC_ID#_heading">',
'  <header class="amc-TTerminalWindow-bar">',
'    <span class="amc-TTerminalWindow-lights" aria-hidden="true"><span class="amc-TTerminalWindow-light amc-TTerminalWindow-light--close"></span><span class="amc-TTerminalWindow-light amc-TTerminalWindow-light--min"></span><span class="amc-TTerminalWindow-light amc-TTerminalWindow-light--max"></span></span>',
'    <h2 class="amc-TTerminalWindow-title" id="#REGION_STATIC_ID#_heading"><span class="amc-TTerminalWindow-icon fa #ICON_CSS_CLASSES#" aria-hidden="true"></span><span class="amc-TTerminalWindow-text">#TITLE#</span><span class="amc-TTerminalWindow-caret" aria-hidden="true"></span></h2>',
'    <div class="amc-TTerminalWindow-actions">#HELP##EDIT##CHANGE##COPY##DELETE##CREATE#</div>',
'  </header>',
'  <div class="amc-TTerminalWindow-pane">',
'    <div class="amc-TTerminalWindow-body">#BODY##SUB_REGIONS#</div>',
'    <footer class="amc-TTerminalWindow-status">#PREVIOUS##CLOSE##NEXT#</footer>',
'  </div>',
'</section>'))
,p_page_plug_template_name=>'AMC Terminal Window'
,p_internal_name=>'AMC_TPL_TERMINAL_WINDOW'
,p_css_file_urls=>'#APP_FILES#amc-templates/amc-tpl-terminal-window.css'
,p_theme_id=>42
,p_default_label_alignment=>'RIGHT'
,p_default_field_alignment=>'LEFT'
,p_translate_this_template=>'N'
,p_template_comment=>'Region template that draws a terminal window around any region. The title bar shows three window dots from the danger, warning and success palette colors and the region title centered in monospace after a prompt glyph, or after the region icon when one is set. Buttons in Help, Edit, Change, Copy, Delete and Create sit at the end of the title bar; Previous, Close and Next sit in a status line under the content. By default the bezel uses inverse theme colors, so it is dark in light styles and light in dark styles, while the content pane keeps the normal surface so reports and forms stay native. Template options: Theme chrome keeps the bezel in the normal theme colors, Console pane turns the content pane inverse too and is meant for text, logs, charts and cards, Scanlines adds CRT lines to the chrome and console, Blinking caret adds a caret after the title, Monospace body sets the content font to monospace, and No body padding. Under reduced motion the caret stays solid; in forced-colors mode the window becomes a plain bordered box.'
);
end;
/
